import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.CRFziyHp.js";const u=JSON.parse('{"title":"运营模块组件","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/components-marketing.md","filePath":"features/ui-editor/components-marketing.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/components-marketing.md"};function n(s,t,i,l,h,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="运营模块组件" tabindex="-1">运营模块组件 <a class="header-anchor" href="#运营模块组件" aria-label="Permalink to &quot;运营模块组件&quot;">​</a></h1><p>运营模块包含 <strong>3 个组件</strong>，适用于 <strong>应用首页</strong>、<strong>功能页面</strong>、<strong>自定义页面</strong>。在 <strong>服务表单（errand_service）</strong> 页不可用。</p><p>组件库分类：<strong>运营模块</strong>。</p><hr><h2 id="首页榜单-xiaoyi-home-rank-cards" tabindex="-1">首页榜单（xiaoyi-home-rank-cards） <a class="header-anchor" href="#首页榜单-xiaoyi-home-rank-cards" aria-label="Permalink to &quot;首页榜单（xiaoyi-home-rank-cards）&quot;">​</a></h2><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>横向滑动的 <strong>三榜卡片</strong>：<strong>热帖榜</strong>、<strong>话题榜</strong>、<strong>优质用户榜</strong>。每榜展示若干条排行内容，有数据才显示对应卡片。</p><p>支持两种数据来源：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><strong>静态配置</strong></td><td>榜单数据写入页面配置；编辑器画布始终展示演示数据</td></tr><tr><td><strong>区域发现接口</strong></td><td>用户端运行时请求接口，一次返回热帖、话题、优质用户等数据并覆盖静态配置</td></tr></tbody></table><p>开启接口后，可按 <strong>当前用户区域</strong> 或 <strong>固定区域 ID</strong> 拉取数据；留空区域 ID 表示全站统计。</p><div class="tip custom-block"><p class="custom-block-title">适用场景</p><p>首页运营位、发现页热点引导。常与笔记列表、筛选标签搭配使用。</p></div><h3 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td><strong>区域发现接口</strong></td><td></td><td></td></tr><tr><td>使用接口数据</td><td>开启后用户端请求接口</td><td>关闭</td></tr><tr><td>跟随当前区域</td><td>为「是」时传用户当前区域 ID</td><td>是</td></tr><tr><td>固定 region_id</td><td>不跟随区域时填写；留空=全站</td><td>—</td></tr><tr><td>接口 limit</td><td>四段数据各取 Top N，服务端上限 50</td><td>10</td></tr><tr><td><strong>榜单</strong></td><td></td><td></td></tr><tr><td>总开关</td><td>显示 / 隐藏整个榜单区域</td><td>显示</td></tr><tr><td>每类条数 limit</td><td>卡片内展示行数（与接口 limit 独立）</td><td>3</td></tr><tr><td><strong>滑动提示</strong></td><td></td><td></td></tr><tr><td>显示提示</td><td>至少 2 张卡片可见且可横滑时出现</td><td>显示</td></tr><tr><td>提示文案</td><td>底部滑动引导文字</td><td>左右滑动查看更多</td></tr><tr><td>提示字号 / 字重 / 颜色</td><td>滑动提示样式</td><td>20rpx / 500 / #999999</td></tr><tr><td><strong>卡片外观</strong></td><td></td><td></td></tr><tr><td>卡片间距</td><td>横向卡片间距</td><td>20rpx</td></tr><tr><td>卡片圆角</td><td>单张榜单卡片圆角</td><td>24rpx</td></tr><tr><td><strong>各榜（热帖 / 话题 / 优质）</strong></td><td>分别配置</td><td></td></tr><tr><td>启用</td><td>是否显示该榜</td><td>默认均启用</td></tr><tr><td>顺序 order</td><td>横向排列顺序</td><td>热帖 1、话题 2、优质 3</td></tr><tr><td>标题文案</td><td>卡片顶部标题</td><td>热帖榜 / 话题榜 / 优质榜单</td></tr><tr><td>显示标题图标</td><td>标题左侧图标</td><td>显示</td></tr><tr><td>标题图标名</td><td>留空用默认（热帖 fire-o、话题 chat-o、优质 star-o）</td><td>—</td></tr><tr><td>图标大小 / 颜色</td><td>标题图标样式</td><td>22rpx / #000000</td></tr><tr><td>标题字号 / 颜色 / 字重</td><td>标题文字样式</td><td>26rpx / #000000 / 700</td></tr><tr><td><strong>点击动作</strong></td><td></td><td></td></tr><tr><td>话题榜卡片 / 热帖榜卡片 / 优质榜卡片</td><td>点击整张卡片</td><td>可选</td></tr><tr><td>话题行 / 热帖行 / 优质用户行</td><td>点击列表某一行</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><p>组件根容器（宽高、外边距、内边距、背景、圆角、边框、透明度、阴影等）请在右侧顶部切换到 <strong>「样式」</strong> Tab 编辑，与画布其他组件一致。</p><p>属性 Tab 内可配：<strong>滑动提示</strong>、<strong>卡片外观</strong>、<strong>各榜标题与图标</strong>。</p><h3 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>仅 <strong>home / feature / custom</strong> 页面可添加</li><li>接口模式下，编辑器画布仍显示演示数据，需保存后在客户端验证</li><li>榜单 type 对应：热帖 <code>note</code>、话题 <code>topic</code>、优质 <code>user</code></li></ul><hr><h2 id="双卡行动-xiaoyi-dual-action-cards" tabindex="-1">双卡行动（xiaoyi-dual-action-cards） <a class="header-anchor" href="#双卡行动-xiaoyi-dual-action-cards" aria-label="Permalink to &quot;双卡行动（xiaoyi-dual-action-cards）&quot;">​</a></h2><h3 id="说明-1" tabindex="-1">说明 <a class="header-anchor" href="#说明-1" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>左右 <strong>两张行动卡片</strong> 并排展示，用于引导用户完成两个并列操作（如「完善资料」「邀请分享」）。每张卡含气泡图标/图片、标题、描述；右卡可额外配置右侧插图。</p><p>两卡宽度按 <strong>flex 比例</strong> 分配（如左 42、右 58）。</p><h3 id="属性-1" tabindex="-1">属性 <a class="header-anchor" href="#属性-1" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td><strong>布局</strong></td><td></td><td></td></tr><tr><td>两卡间距</td><td>左右卡片间距</td><td>12rpx</td></tr><tr><td>单卡内边距</td><td>卡片内部留白</td><td>24rpx</td></tr><tr><td>左卡宽度占比</td><td>flex 比例</td><td>42</td></tr><tr><td>右卡宽度占比</td><td>flex 比例</td><td>58</td></tr><tr><td><strong>左卡</strong></td><td></td><td></td></tr><tr><td>背景色 / 圆角</td><td>左卡外观</td><td>— / 24rpx</td></tr><tr><td>气泡内容</td><td>字体图标 或 图片（二选一）</td><td>字体图标</td></tr><tr><td>图标名 / 前缀 / 颜色</td><td>选图标时配置</td><td>label-o 等</td></tr><tr><td>图片 URL</td><td>选图片时配置</td><td>—</td></tr><tr><td>气泡宽 / 高</td><td>留空自适应</td><td>—</td></tr><tr><td>标题 / 描述</td><td>主副文案</td><td>—</td></tr><tr><td>标题字号 / 描述字号</td><td>文字大小</td><td>—</td></tr><tr><td>标题颜色 / 描述颜色</td><td>文字颜色</td><td>—</td></tr><tr><td>标题字重</td><td>标题粗细</td><td>—</td></tr><tr><td><strong>右卡</strong></td><td>字段同左卡，另增：</td><td></td></tr><tr><td>右侧插图 URL</td><td>卡片右侧装饰图</td><td>—</td></tr><tr><td>插图宽 / 高 / 圆角</td><td>插图尺寸</td><td>—</td></tr><tr><td>文与图间距</td><td>文字区与插图间距</td><td>—</td></tr><tr><td><strong>气泡公共</strong></td><td>左右卡共用</td><td></td></tr><tr><td>气泡背景</td><td>图标/图片容器背景</td><td>—</td></tr><tr><td>气泡内边距 / 圆角</td><td>气泡容器样式</td><td>—</td></tr><tr><td>气泡内图标字号</td><td>字体图标大小</td><td>—</td></tr><tr><td><strong>点击动作</strong></td><td></td><td></td></tr><tr><td>左卡 leftClickAction</td><td>点击左卡</td><td>可选</td></tr><tr><td>右卡 rightClickAction</td><td>点击右卡</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-1" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-1" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><p>根容器宽高、外边距、内边距、背景、圆角、边框等 → <strong>「样式」</strong> Tab。</p><p>属性 Tab 内：<strong>布局</strong>、<strong>左卡</strong>、<strong>右卡</strong>、<strong>气泡公共</strong>、<strong>点击动作</strong>。</p><h3 id="约束-1" tabindex="-1">约束 <a class="header-anchor" href="#约束-1" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>仅 <strong>home / feature / custom</strong> 页面可添加</li><li>左、右卡气泡内容为 <strong>图标或图片二选一</strong>，不可同时生效</li></ul><hr><h2 id="小程序广告-xiaoyi-mp-ad" tabindex="-1">小程序广告（xiaoyi-mp-ad） <a class="header-anchor" href="#小程序广告-xiaoyi-mp-ad" aria-label="Permalink to &quot;小程序广告（xiaoyi-mp-ad）&quot;">​</a></h2><h3 id="说明-2" tabindex="-1">说明 <a class="header-anchor" href="#说明-2" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>用于在页面中插入 <strong>微信小程序流量主广告</strong>，同时在 <strong>H5 / App</strong> 端展示 <strong>占位图</strong>，便于编辑器预览与非小程序环境投放自定义素材。</p><table tabindex="0"><thead><tr><th>运行端</th><th>展示内容</th></tr></thead><tbody><tr><td><strong>微信小程序</strong></td><td>原生模板广告（ad-custom），需配置 unit-id</td></tr><tr><td><strong>H5 / App</strong></td><td>占位图 + 可选点击动作</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">前置条件</p><p>unit-id 须在微信公众平台 <strong>流量主</strong> 后台创建广告位后获取。未开通流量主时小程序端无广告展示。</p></div><h3 id="属性-2" tabindex="-1">属性 <a class="header-anchor" href="#属性-2" aria-label="Permalink to &quot;属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th><th>默认值 / 备注</th></tr></thead><tbody><tr><td><strong>小程序广告</strong></td><td></td><td></td></tr><tr><td>广告位 unit-id</td><td>流量主后台获取的广告单元 ID</td><td>必填（小程序端）</td></tr><tr><td>自动刷新间隔（秒）</td><td>0 表示不刷新；≥30 才生效</td><td>0</td></tr><tr><td><strong>占位图（H5/App）</strong></td><td></td><td></td></tr><tr><td>图片地址</td><td>占位图 URL 或静态路径</td><td>—</td></tr><tr><td>显示模式</td><td>图片缩放模式（如 widthFix 等）</td><td>widthFix</td></tr><tr><td>占位图高度</td><td>留空则随宽度自适应</td><td>—</td></tr><tr><td>占位图圆角</td><td>占位图圆角</td><td>0</td></tr><tr><td><strong>点击事件</strong></td><td></td><td></td></tr><tr><td>占位图点击动作</td><td>H5/App 端点击占位图时的跳转</td><td>可选</td></tr></tbody></table><h3 id="内嵌样式分组-2" tabindex="-1">内嵌样式分组 <a class="header-anchor" href="#内嵌样式分组-2" aria-label="Permalink to &quot;内嵌样式分组&quot;">​</a></h3><p>根容器样式（宽、高、外边距、内边距、背景等）→ <strong>「样式」</strong> Tab。</p><p>属性 Tab 内：<strong>小程序广告</strong>、<strong>占位图</strong>、<strong>点击事件</strong>。</p><h3 id="约束-2" tabindex="-1">约束 <a class="header-anchor" href="#约束-2" aria-label="Permalink to &quot;约束&quot;">​</a></h3><ul><li>仅 <strong>home / feature / custom</strong> 页面可添加</li><li><strong>unit-id</strong> 仅影响微信小程序端；H5/App 始终显示占位图</li><li>占位图点击动作 <strong>不作用于</strong> 微信小程序原生广告（由微信 SDK 处理）</li><li>自动刷新间隔须 <strong>≥30 秒</strong> 才会生效</li></ul><hr><h2 id="系列导航" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航" aria-label="Permalink to &quot;系列导航&quot;">​</a></h2><ul><li>上一篇：<a href="/features/ui-editor/components-community">社区内容组件</a></li><li>下一篇：<a href="/features/ui-editor/components-form">表单/服务组件</a></li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ui-editor/page-types#各类型可用组件对照">页面类型说明 — 各类型可用组件</a></li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/ui-editor/">UI 编辑器概览</a></li></ul>',48)])])}const p=d(e,[["render",n]]);export{u as __pageData,p as default};
